/// <summary>
/// PaffH 05.11.25
/// last modified: PaffH 25.11.25
/// initialize class
/// </summary>
/// <param name = "_formRun">FormRun</param>
public void initFromFormRun(FormRun _formRun)
{
    super(_formRun);
    NDXBVEMailRequestHeader_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestHeader));
    NDXBVEMailRequestHeaderAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestHeaderAIDecisionBasis));
    NDXBVEMailRequestHeaderAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestHeaderAIInfo));
    NDXBVEMailRequestPlaner_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestPlaner));
    NDXBVEMailRequestPlanerAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestPlanerAIDecisionBasis));
    NDXBVEMailRequestPlanerAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestPlanerAIInfo));
    NDXBVEMailRequestInstaller_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestInstaller));
    NDXBVEMailRequestInstallerAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestInstallerAIDecisionBasis));
    NDXBVEMailRequestInstallerAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestInstallerAIInfo));
    NDXBVEMailRequestBuildingOwner_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestBuildingOwner));
    NDXBVEMailRequestBuildingOwnerAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestBuildingOwnerAIDecisionBasis));
    NDXBVEMailRequestBuildingOwnerAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestBuildingOwnerAIInfo));
    NDXBVEMailRequestADA_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestADA));
    NDXBVEMailRequestADAAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestADAAIDecisionBasis));
    NDXBVEMailRequestADAAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestADAAIInfo));
    NDXBVEMailRequestLine_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestLine));
    NDXBVEMailRequestLineAIDecisionBasis_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestLineAIDecisionBasis));
    NDXBVEMailRequestLineAIInfo_DS = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXBVEMailRequestControlCenterAIDB, NDXBVEMailRequestLineAIInfo));
}

/// <summary>
/// PaffH 05.11.25
/// constructor
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXBVEMailRequestControlCenterAIDBForm</returns>
public static NDXBVEMailRequestControlCenterAIDBForm newFromForm(FormRun _formRun)
{
    NDXBVEMailRequestControlCenterAIDBForm formHandler;
    formHandler = new NDXBVEMailRequestControlCenterAIDBForm();
    formHandler.initFromFormRun(_formRun);
    return formHandler;
}

/// <summary>
/// PaffH 05.11.25
/// last modified: PaffH 25.11.25
/// set text to HtmlViewerControl
/// </summary>
/// <param name = "_control">HtmlViewerControl</param>
/// <param name = "_text">str</param>
/// <param name = "_textInfo">str ('')</param>
/// <param name = "_find">str ('')</param>
/// <param name = "_list">List (new List(Types::String))</param>
public void setHTML(HtmlViewerControl _control, str _text, str _textInfo = '', str _find = '', List _list = new List(Types::String))
{
    str findText = _find;
    if (_text || _textInfo)
    {
        NDXBuildHTMLContract contractHtml = NDXBuildHTMLContract::construct();
        contractHtml.parmHtmlText1(_text);
        contractHtml.parmHtmlText2(_textInfo);
        str text = helperHTML.buildHtmlFromContract(contractHtml);
        if (findText)
        {
            text = helperHTML.findAndSetTag(text, findText);
        }
        if (_list.elements())
        {
            ListEnumerator listEnum = _list.getEnumerator();
            while (listEnum.moveNext())
            {
                findText = listEnum.current();
                if (findText)
                {
                    text = helperHTML.findAndSetTag(text, findText);
                }
            }
        }
        _control.parmHtml(text);
    }
    else
    {
        _control.parmHtml(NDXHelperHTMLBVEMailRequestControlCenterAIDB::emptyHtml());
    }
}

/// <summary>
/// PaffH 08.11.25
/// last modified: PaffH 05.12.25
/// </summary>
/// <param name = "_sectionGroup"></param>
/// <param name = "_sectionType"></param>
private void setDesignFromSectionGroupContract(NDXBVEmailRequestAIDBSectionGroupContract _sectionGroup, NDXBVEmailRequestSectionType _sectionType)
{
    FormTabPageControl formTabPage;
    FormGroupControl formGroupArrange;
    FormGroupControl formGroupControl;
    FormGroupControl formGroupControlDyn;
    FormStringControl formStringControl;
    FormRealControl formRealControl;
    FormDateControl formDateControl;
    FormCheckBoxControl formCheckBoxControl;
    FormDateTimeControl formDateTimeControl;
    HtmlViewerControl htmlViewerControl;
    str htmlValue;
    str strfieldInfo;
    int dsID;
    str fieldToFind;

    NDXBVEmailRequestAIDBFieldContract aiField = _sectionGroup.parmAiField();
    NDXBVEmailRequestAIDBFieldDecisionBaseContract aiFieldDecisionBase = _sectionGroup.parmAiFieldDecisionBase();
    NDXBVEmailRequestAIDBFieldInfoContract aiFieldInfo = _sectionGroup.parmAiFieldInfo();

    switch (_sectionType)
    {
        case NDXBVEmailRequestSectionType::HeaderAIDBDocument :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageHeaderAIDBDocument));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Organisation :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageOrganisation));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Project :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageProject));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Request :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageRequest));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::ContactPerson :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageContactPerson));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Demand :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageDemand));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Email :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageEmail));
            dsID = NDXBVEMailRequestHeader_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Planer :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPagePlaner));
            dsID = nDXBVEMailRequestPlaner_DS.id();
            break;
        case NDXBVEmailRequestSectionType::Installer :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageInstaller));
            dsID = nDXBVEMailRequestInstaller_DS.id();
            break;
        case NDXBVEmailRequestSectionType::BuildingOwner :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageBuildingOwner));
            dsID = NDXBVEMailRequestBuildingOwner_DS.id();
            break;
        case NDXBVEmailRequestSectionType::ADA :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageADA));
            dsID = NDXBVEMailRequestADA_DS.id();
            break;
        case NDXBVEmailRequestSectionType::ItemLine :
            formTabPage = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormTabPageLine));
            formGroupControlDyn = thisFormRun.design().controlName(formControlStr(NDXBVEMailRequestControlCenterAIDB, FormGroupLine));
            dsID = NDXBVEMailRequestLine_DS.id();
            break;
        default :
            throw Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", _sectionType));
    }
    if (aiField.parmFieldId() || aiFieldDecisionBase.parmFieldId())
    {
        if (formGroupControlDyn)
        {
            formGroupArrange = formGroupControlDyn.addControl(FormControlType::Group, _sectionGroup.parmFormArrangeGroupName());
        }
        else
        {
            formGroupArrange = formTabPage.addControl(FormControlType::Group, _sectionGroup.parmFormArrangeGroupName());
        }
        formGroupArrange.widthMode(FormWidth::SizeToAvailable);
        formGroupArrange.columns(2);
        formGroupArrange.visible(true);
        fieldToFind = aiField.parmFieldValueAsStr();

        if (aiField.parmFieldId())
        {
            formGroupControl = formGroupArrange.addControl(FormControlType::Group, aiField.parmFormGroupName());
            formGroupControl.caption(aiField.parmcaption());
            formGroupControl.widthMode(FormWidth::Manual);
            formGroupControl.width(400);
            formGroupControl.visible(true);

            switch (aiField.parmFieldType())
            {
                case Types::Date:
                    formDateControl = formGroupControl.addDataFieldWithName(dsID, aiField.parmFieldId(), aiField.parmFormFieldName());
                    formDateControl.showLabel(false);
                    formDateControl.widthMode(FormWidth::SizeToAvailable);
                    formDateControl.allowEdit(false);
                    break;
                case Types::UtcDateTime:
                    formDateTimeControl = formGroupControl.addDataFieldWithName(dsID, aiField.parmFieldId(), aiField.parmFormFieldName());
                    formDateTimeControl.showLabel(false);
                    formDateTimeControl.widthMode(FormWidth::SizeToAvailable);
                    formDateTimeControl.allowEdit(false);
                    break;
                case Types::Real:
                    formRealControl = formGroupControl.addDataFieldWithName(dsID, aiField.parmFieldId(), aiField.parmFormFieldName());
                    formRealControl.showLabel(false);
                    formRealControl.widthMode(FormWidth::SizeToAvailable);
                    formRealControl.allowEdit(false);
                    break;
                case Types::Enum:
                    formCheckBoxControl = formGroupControl.addDataFieldWithName(dsID, aiField.parmFieldId(), aiField.parmFormFieldName());
                    formCheckBoxControl.showLabel(false);
                    formCheckBoxControl.allowEdit(false);
                    break;
                default:
                    formStringControl = formGroupControl.addDataFieldWithName(dsID, aiField.parmFieldId(), aiField.parmFormFieldName());
                    formStringControl.showLabel(false);
                    formStringControl.widthMode(FormWidth::SizeToAvailable);
                    formStringControl.allowEdit(false);
                    formStringControl.displayHeightMode(AutoMode::Fixed);
                    formStringControl.displayHeightValue(1);
            }
        }

        if (aiFieldDecisionBase.parmFieldId())
        {
            formGroupControl = formGroupArrange.addControl(FormControlType::Group, aiFieldDecisionBase.parmFormGroupName());
            formGroupControl.caption(aiFieldDecisionBase.parmcaption());
            formGroupControl.widthMode(FormWidth::SizeToAvailable);
            formGroupControl.visible(true);

            htmlViewerControl = formGroupControl.addControlEx(classStr(HtmlViewerControl), aiFieldDecisionBase.parmFormFieldName());
            htmlViewerControl.heightMode(FormHeight::Auto);
            htmlViewerControl.widthMode(FormWidth::SizeToAvailable);
            htmlValue = aiFieldDecisionBase.parmFieldValueAsStr();

            strfieldInfo = aiFieldInfo ? aiFieldInfo.parmFieldValueAsStr() : '';
            this.setHTML(htmlViewerControl, htmlValue, strfieldInfo, fieldToFind);
        }
    }
}

/// <summary>
/// PaffH 07.11.25
/// last modified: PaffH 11.11.25
/// add controls to form
/// </summary>
public void addControls()
{

    contract = NDXBVEmailRequestAIDBContract::construct();

    ListEnumerator enumSection = contract.parmSections().getEnumerator();
    ListEnumerator enumSectionGroup;
    while (enumSection.moveNext())
    {
        NDXBVEmailRequestAIDBSectionContract contractSection = enumSection.current();
        if (contractSection is NDXBVEmailRequestAIDBSectionContactPersonContract)
        {
            NDXBVEmailRequestAIDBSectionContactPersonContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionContactPersonContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::ContactPerson);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract)
        {
            NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionHeaderAIDBDocumentContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::HeaderAIDBDocument);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionProjectContract)
        {
            NDXBVEmailRequestAIDBSectionProjectContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionProjectContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Project);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionRequestContract)
        {
            NDXBVEmailRequestAIDBSectionRequestContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionRequestContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Request);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionOrganisationContract)
        {
            NDXBVEmailRequestAIDBSectionOrganisationContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionOrganisationContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Organisation);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionPlanerContract)
        {
            NDXBVEmailRequestAIDBSectionPlanerContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionPlanerContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Planer);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionInstallerContract)
        {
            NDXBVEmailRequestAIDBSectionInstallerContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionInstallerContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Installer);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionADAContract)
        {
            NDXBVEmailRequestAIDBSectionADAContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionADAContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::ADA);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionBuildingOwnerContract)
        {
            NDXBVEmailRequestAIDBSectionBuildingOwnerContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionBuildingOwnerContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::BuildingOwner);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionLineItemContract)
        {
            NDXBVEmailRequestAIDBSectionLineItemContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionLineItemContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::ItemLine);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionDemandContract)
        {
            NDXBVEmailRequestAIDBSectionDemandContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionDemandContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Demand);
            }
        }
        else if (contractSection is NDXBVEmailRequestAIDBSectionEmailContract)
        {
            NDXBVEmailRequestAIDBSectionEmailContract contractLocal = contractSection as NDXBVEmailRequestAIDBSectionEmailContract;
            enumSectionGroup = contractLocal.parmSectionGroups().getEnumerator();
            while (enumSectionGroup.moveNext())
            {
                sectionGroup = enumSectionGroup.current();
                this.setDesignFromSectionGroupContract(sectionGroup, NDXBVEmailRequestSectionType::Email);
            }
        }
        else
        {
            Error(strFmt("@NDXBase:NDXTheElementIsNotTakenIntoAccount", contractSection.toString()));
        }
    }
}

/// <summary>
/// PaffH 08.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_sectionGroup">NDXBVEmailRequestAIDBSectionGroupContract</param>
private void fillHTMLControlFromNDXBVEmailRequestAIDBSectionGroupContract(NDXBVEmailRequestAIDBSectionGroupContract _sectionGroup)
{
    List list = new List(Types::String);
    boolean populateList = false;
    populateList = (_sectionGroup.parmAiFieldDecisionBase().parmRecord().TableId == tableNum(NDXBVEMailRequestHeaderAIDecisionBasis))
        && (_sectionGroup.parmAiFieldDecisionBase().parmFieldId() == fieldNum(NDXBVEMailRequestHeaderAIDecisionBasis, AIDBDocument));
    if (populateList)
    {
        contract.populateAll(this);
        list = contract.findAllFieldValuesAsString();
    }
    HtmlViewerControl htmlViewerControl = thisFormRun.design().controlName(_sectionGroup.parmAiFieldDecisionBase().parmFormFieldName());
    if (htmlViewerControl)
    {
        str htmlValue = _sectionGroup.parmAiFieldDecisionBase().parmFieldValueAsStr();
        str htmlValueInfo = _sectionGroup.parmAiFieldInfo() ? _sectionGroup.parmAiFieldInfo().parmFieldValueAsStr() : '';
        str findValue = _sectionGroup.parmAiField().parmFieldValueAsStr();
        this.setHTML(htmlViewerControl, htmlValue, htmlValueInfo, findValue, list);
    }
}

